  "reviewedBy": "compliance-officer-jose"
}

request.description:
Record that a SAR was filed for a verification. Regulatory compliance.

Request body (Map<String,String>): { sarReferenceNumber, filedBy }

Response 200: { verificationId, sarReferenceNumber, filedAt, status: 'SAR_RECORDED' }

Trigger manual re-verification for a user (compliance request or 90-day review).

Request body (Map<String,String>): { reason: String (default: COMPLIANCE_REQUESTED) }

Response 202 Accepted: { userId, status: 'RE_VERIFICATION_QUEUED', reason, queuedAt }
